    imageHint: "Tai Mo Shan mountain peak with mist",
    descriptionAdvanced: {
      de: "Mit einer Höhe von 957 Metern ist der Tai Mo Shan der unangefochtene Gipfel Hongkongs und dominiert das Landschaftsbild der New Territories. Dieser erloschene Vulkan zeugt von der feurigen geologischen Vergangenheit der Region, wobei seine Flanken heute von weiten Grasflächen und Granitformationen geprägt sind. Aufgrund seiner exponierten Lage herrscht hier ein deutlich kühleres Mikroklima als in den tiefer gelegenen Stadtteilen; im Winter können die Temperaturen sogar unter den Gefrierpunkt fallen. Oft verhüllt dichter Nebel den Gipfel, was dem Berg eine mystische Atmosphäre verleiht. Wanderer nutzen den MacLehose Trail, um die Spitze zu erreichen, von der aus sich bei klarem Wetter ein Panorama über das gesamte Territorium bis hin zur Grenze nach Shenzhen erstreckt. In den unteren Lagen finden sich Wasserfälle wie die Ng Tung Chai Falls.",
      hu: "A 957 méter magas Tai Mo Shan Hongkong legmagasabb hegycsúcsa, amely az Új Területek szívében magasodik. Ez az egykori vulkán mintegy 140 millió évvel ezelőtt volt aktív, mára azonban békés, füves lankák és hatalmas gránitsziklák jellemzik. A hegy különleges mikroklímával rendelkezik: gyakran burkolózik sűrű ködbe, és az itteni hőmérséklet jóval alacsonyabb, mint a városi betondzsungelben. A téli hónapokban nem ritka a zúzmara vagy a fagy sem, ami Hongkongban igazi ritkaságnak számít. A MacLehose-túraútvonal érinti a csúcs alatti területeket, ahonnan tiszta időben lenyűgöző kilátás nyílik a Viktória-kikötőre, a környező szigetekre és az északra fekvő Shenzhen felhőkarcolóira is. A hegyoldalakon található egykori teateraszok a terület mezőgazdasági múltjára emlékeztetnek.",
      ro: "Muntele Tai Mo Shan, având o înălțime de 957 de metri, reprezintă cel mai înalt punct din Hong Kong și este situat în inima Noilor Teritorii. Acest vulcan stins, a cărui activitate datează de peste 140 de milioane de ani, domină peisajul înconjurător prin pantele sale line acoperite de iarbă și bolovani de granit. Datorită altitudinii sale, muntele are un microclimat specific, fiind adesea învăluit în ceață densă și înregistrând cele mai scăzute temperaturi din întreaga regiune; iarna, înghețul este un fenomen obișunuit pe vârf. Accesul către culme se face de obicei prin traseul MacLehose, oferind drumeților panorame spectaculoase care se întind de la Victoria Harbour până la granița cu orașul Shenzhen din China continentală. Versanții săi adăpostesc cascade pitorești și rămășițele vechilor terase unde odinioară se cultiva ceaiul verde.",
      en: "Standing at 957 meters, Tai Mo Shan is the highest peak in Hong Kong, centrally located within the New Territories. As an extinct volcano that was active over 140 million years ago, its geological history is visible in the weathered granite boulders scattered across its grassy slopes. The mountain is famous for its unique microclimate, frequently shrouded in thick mist and experiencing temperatures significantly lower than the urban areas below. During winter, it is one of the few places in Hong Kong where sub-zero temperatures and frost are recorded. The MacLehose Trail provides hikers with access to its upper reaches, offering panoramic views of the entire territory, from Victoria Harbour to the skyscrapers of Shenzhen, on clear days. The lower slopes are home to the Ng Tung Chai waterfalls and remnants of historical tea terraces.",
      es: "El Tai Mo Shan es la montaña más alta de Hong Kong (957 m) y se localiza en los Nuevos Territorios. Es un destino predilecto para senderistas y amantes de la naturaleza. Forma parte del Parque Rural Tai Mo Shan, fundado en 1979. La cumbre suele estar envuelta en nubes y ofrece un ambiente más fresco. La flora incluye bosques subtropicales y pastizales. En la cima hay una estación meteorológica del Observatorio de Hong Kong. La montaña también es conocida por albergar especies raras de mariposas.",
      pt: "O Tai Mo Shan é, com 957 metros, a montanha mais alta de Hong Kong e situa-se nos Novos Territórios. A montanha é um destino popular para caminhantes e amantes da natureza. Faz parte do Parque Rural de Tai Mo Shan, fundado em 1979. O cume está frequentemente envolto em nuvens e oferece um ambiente mais fresco. A flora inclui florestas subtropicais e pastagens. No cume existe uma estação meteorológica do Observatório de Hong Kong. A montanha é também conhecida pelas suas espécies raras de borboletas.",
      fr: "Le Tai Mo Shan est le plus haut sommet de Hong Kong (957 mètres) et se situe dans les Nouveaux Territoires. La montagne est une destination prisée des randonneurs et des amoureux de la nature. Elle fait partie du parc rural de Tai Mo Shan, créé en 1979. Le sommet est souvent enveloppé de nuages et offre un environnement plus frais. La flore comprend des forêts subtropicales et des prairies. Au sommet se trouve une station météorologique de l'Observatoire de Hong Kong. La montagne est également réputée pour ses espèces rares de papillons.",
    },
