      ro: ["Altitudine: 957 m", "Clasare: cel mai înalt din Hong Kong", "Parte a Parcului Natural Tai Mo Shan (1979)", "Temperatura medie pe vârf: 15 °C", "Precipitații anuale: peste 2.500 mm", "Specii de fluturi: peste 100"],
      en: ["Height: 957 m (3,140 ft)", "Rank: Highest mountain in Hong Kong", "Part of Tai Mo Shan Country Park (est. 1979)", "Average summit temperature: 15 °C (59 °F)", "Annual rainfall: over 2,500 mm (98 in)", "Butterfly species: over 100"],
      es: ["Altura: 957 metros", "Rango: Montaña más alta de Hong Kong", "Parte del Parque Rural Tai Mo Shan (fundado en 1979)", "Temperatura media en la cima: 15 °C (aprox. 10 °C más fresca que en la base)", "Precipitación anual: más de 2.500 mm", "Número de especies de mariposas: más de 100"],
      pt: ["Altitude: 957 metros", "Classificação: Montanha mais alta de Hong Kong", "Parte do Parque Rural de Tai Mo Shan (fundado em 1979)", "Temperatura média no cume: 15 °C (cerca de 10 °C mais fresco do que na base)", "Precipitação anual: mais de 2.500 mm", "Número de espécies de borboletas: mais de 100"],
