    description: {
      de: "Der Sunset Peak ist der dritthöchste Berg in Hongkong und liegt auf Lantau Island. Er ist bekannt für seine historischen Steinhütten und weiten Grasflächen.",
      hu: "A Sunset-csúcs Hongkong harmadik legmagasabb hegye Lantau szigetén. Történelmi kőkunyhóiról és hatalmas füves területeiről ismert.",
      ro: "Vârful Sunset este al treilea cel mai înalt munte din Hong Kong, pe insula Lantau. Este cunoscut pentru cabanele de piatră și pajiști.",
      en: "Sunset Peak is the third highest mountain in Hong Kong, located on Lantau Island. It is known for its stone shacks and vast grasslands.",
      es: "Sunset Peak es la tercera montaña más alta de Hong Kong y se encuentra en la isla de Lantau. Es famosa por sus históricas cabañas de piedra y extensas praderas.",
      pt: "O Sunset Peak é a terceira montanha mais alta de Hong Kong, situada na ilha de Lantau. É conhecido pelas suas cabanas de pedra históricas e vastas áreas de pasto.",
      fr: "Sunset Peak est la troisième plus haute montagne de Hong Kong, située sur l'île de Lantau. Il est célèbre pour ses cabanes en pierre historiques et ses vastes prairies.",
    },
