      de: ["Höhe von 869 Metern", "Dritthöchster Berg Hongkongs", "Bekannt für Sonnenuntergänge", "Historische Steinhütten vorhanden"],
      hu: ["Magassága 869 méter", "Hongkong harmadik legmagasabb hegye", "Népszerű naplemente nézőhely", "Történelmi kőkunyhók a hegyen"],
