    imageHint: "Sunset Peak stone shacks landscape",
    descriptionAdvanced: {
      de: "Der Sunset Peak, lokal als Tai Tung Shan bekannt, erhebt sich auf eine Höhe von 869 Metern und ist damit der dritthöchste Gipfel Hongkongs. Er liegt auf der Insel Lantau, eingebettet zwischen dem Mui Wo Tal und dem Tung Chung Becken. Berühmt ist der Berg vor allem für seine einzigartigen Steinhütten, das sogenannte Lantau Mountain Camp, die in den 1920er Jahren von Missionaren als Sommerresidenzen erbaut wurden. Diese kleinen Hütten verleihen der kargen Berglandschaft einen fast mystischen Charakter. Besonders im Herbst zieht der Sunset Peak Scharen von Wanderern an, wenn die weiten Hänge mit dem silbrig glänzenden Chinaschilf (Miscanthus) bedeckt sind. Der Aufstieg über den Lantau Trail (Abschnitt 2) gilt als anspruchsvoll, belohnt jedoch mit einem Panorama, das bei klarem Wetter bis zum Südchinesischen Meer und den umliegenden Inseln reicht. Wie der Name schon sagt, ist der Gipfel der ideale Ort, um spektakuläre Sonnenuntergänge zu beobachten, wenn das Licht die goldenen Grasflächen und die historischen Ruinen in ein warmes Licht taucht.",
      hu: "A Sunset-csúcs, helyi nevén Tai Tung Shan, 869 méteres magasságával Hongkong harmadik legmagasabb pontja, amely Lantau szigetének szívében magasodik. A hegy legkülönlegesebb látnivalói a gerincen elszórtan található kőkunyhók, amelyeket az 1920-as években misszionáriusok építettek pihenőhelyként, hogy elmeneküljenek a városi hőség elől. Ezek a puritán építmények ma is állnak, és sajátos, történelmi hangulatot kölcsönöznek a tájnak. A túrázók számára a csúcs különösen az őszi hónapokban vonzó, amikor a hegyoldalakat ezüstösen csillogó virágos nádas (Miscanthus) borítja, ami Hongkong egyik legtöbbet fotózott természeti jelensége. A felfelé vezető út a Lantau Trail 2. szakaszán meredek és kihívást jelentő, de a kilátás kárpótol minden fáradtságért: tiszta időben ellátni a Dél-kínai-tengerig és a környező kisebb szigetekig. Ahogy a neve is sugallja, a hegycsúcs a naplementék szerelmeseinek paradicsoma, ahol az aranyba hajló fények felejthetetlen látványt nyújtanak a felhők felett.",
      ro: "Vârful Sunset, cunoscut sub numele local de Tai Tung Shan, se ridică la o altitudine de 869 de metri, fiind al treilea cel mai înalt munte din Hong Kong. Situat pe insula Lantau, acesta oferă un peisaj montan dramatic, foarte diferit de zgârie-norii din centrul orașului. Un element distinctiv al acestui vârf îl reprezintă cabanele istorice din piatră, construite în anii 1920 de către misionari britanici și americani ca refugiu în timpul lunilor toride de vară. Aceste structuri rustice sunt grupate pe platoul montan și oferă un farmec aparte zonei. Perioada cea mai populară pentru vizitare este toamna, când versanții sunt acoperiți de iarbă de argint (Miscanthus), care creează un efect vizual spectaculos sub lumina soarelui. Traseul Lantau Trail, secțiunea 2, care duce spre vârf, este unul solicitant, implicând multe trepte de piatră, dar panorama asupra aeroportului Chek Lap Kok și a insulelor învecinate este impresionantă. Numele muntelui provine de la priveliștile glorioase ale apusului de soare, care atrag fotografi și iubitori de natură dornici să surprindă momentul în care soarele coboară în ocean.",
      en: "Sunset Peak, or Tai Tung Shan in Cantonese, stands at 869 meters, making it the third highest mountain in Hong Kong. Located on Lantau Island, it is a centerpiece of the Lantau South Country Park. The mountain is iconic for the 'Lantau Mountain Camp,' a collection of roughly 20 stone shacks built in the 1920s by missionaries as summer retreats to escape the city's humidity. These historic shelters, scattered along the ridge, provide a unique architectural contrast to the rugged terrain. Sunset Peak is particularly famous for its silvergrass (Miscanthus) season in late autumn, when the slopes turn into a shimmering sea of gold, attracting thousands of photographers. The hike via the Lantau Trail is steep and physically demanding, starting either from Pak Kung Au or Mui Wo, but the rewarding 360-degree views encompass the South China Sea, Pui O Beach, and the distant skyline of Hong Kong Island. As its name implies, the summit is the premier location in the territory to witness the sun setting over the outlying islands, casting long shadows across the historic ruins.",
      es: "Sunset Peak, con 869 metros, es la tercera montaña más elevada de Hong Kong y se sitúa en la isla de Lantau. El pico es célebre por sus espectaculares puestas de sol, que le dan su nombre. El ascenso ofrece vistas excelentes de la isla de Lantau y del Mar de la China Meridional. La cumbre está cubierta de pastizales y alberga una gran variedad de flores silvestres. Sunset Peak es un destino muy popular entre senderistas y fotógrafos.",
      pt: "O Sunset Peak é, com 869 metros, a terceira montanha mais alta de Hong Kong e situa-se na ilha de Lantau. O cume é conhecido pelos seus espetaculares pores do sol, que deram o nome à montanha. A subida oferece uma vista excelente sobre a ilha de Lantau e o Mar da China Meridional. O cume está coberto de pastagens e abriga uma grande variedade de flores silvestres. O Sunset Peak é um destino popular para caminhantes e fotógrafos.",
      fr: "Culminant à 869 mètres, Sunset Peak est le troisième plus haut sommet de Hong Kong, situé sur l'île de Lantau. Le sommet est réputé pour ses couchers de soleil spectaculaires qui lui ont donné son nom. L'ascension offre une vue imprenable sur l'île de Lantau et la mer de Chine méridionale. Le sommet est recouvert de prairies et abrite une grande variété de fleurs sauvages. Sunset Peak est une destination très prisée des randonneurs et des photographes.",
    },
    factsAdvanced: {
      de: ["Höhe: 869 Meter", "Rang: Dritthöchster Berg Hongkongs", "Bekannt für: spektakuläre Sonnenuntergänge", "Aufstiegszeit: ca. 2-3 Stunden", "Vegetation: Grasland mit wilden Azaleen", "Beste Besuchszeit: Oktober bis März"],
      hu: ["Magasság: 869 m", "Rangsor: 3. legmagasabb Hongkongban", "Híres: naplementék", "Túra időtartama: 2-3 óra", "Növényzet: füves puszta, vad azáleák", "Legjobb időszak: október-március"],
      ro: ["Altitudine: 869 m", "Clasare: al treilea cel mai înalt din Hong Kong", "Faimos pentru: apusuri spectaculoase", "Timp de ascensiune: 2-3 ore", "Vegetație: pajiști cu azalee sălbatice", "Perioadă ideală: octombrie-martie"],
      en: ["Height: 869 m (2,851 ft)", "Rank: Third highest peak in Hong Kong", "Known for: spectacular sunset views", "Climbing time: 2-3 hours", "Vegetation: grasslands with wild azaleas", "Best time to visit: October to March"],
      es: ["Altura: 869 metros", "Rango: Tercera montaña más alta de Hong Kong", "Famosa por: puestas de sol espectaculares", "Tiempo de ascenso: aprox. 2-3 horas", "Vegetación: pastizales con azaleas silvestres", "Mejor época para visitar: octubre a marzo"],
      pt: ["Altitude: 869 metros", "Classificação: Terceira montanha mais alta de Hong Kong", "Conhecido por: pores do sol espetaculares", "Tempo de subida: cerca de 2-3 horas", "Vegetação: pastagens com azaleas selvagens", "Melhor época para visitar: outubro a março"],
      fr: ["Altitude : 869 mètres", "Rang : Troisième plus haut sommet de Hong Kong", "Célèbre pour : ses couchers de soleil spectaculaires", "Temps d'ascension : env. 2-3 heures", "Végétation : prairies avec azalées sauvages", "Meilleure période : d'octobre à mars"],
    },
