      es: ["Isla más meridional de Hong Kong", "Conocida por sus rocas de granito", "Grabados rupestres prehistóricos", "Famosa por su sopa de algas"],
      pt: ["Ilha mais a sul de Hong Kong", "Conhecida pelas rochas de granito", "Gravuras rupestres pré-históricas", "Famosa pela sopa de algas"],
      fr: ["Île la plus au sud de Hong Kong", "Connue pour ses rochers de granit", "Gravures rupestres préhistoriques", "Célèbre pour sa soupe aux algues"],
