      pt: ["Área: cerca de 3,7 km²", "População: permanentemente desabitada", "Farol construído: 1911", "Formações de granito do período Cretáceo", "Espécies de corais nas águas circundantes: mais de 100", "Distância de Stanley: cerca de 5 km a sudeste"],
