    facts: {
      de: ["Set aus vier Wasserfällen", "Long Fall ist 35m hoch", "Lage am Tai Mo Shan", "Teil des Kadoorie-Geländes"],
      hu: ["Négy vízesésből álló sorozat", "A Hosszú-esés 35 méter magas", "A Tai Mo Shan oldalában van", "Kadoorie Farm közelében"],
      ro: ["Serie de patru cascade", "Cascada Long are 35m înălțime", "Situată pe Tai Mo Shan", "Aproape de ferma Kadoorie"],
      en: ["Series of four waterfalls", "Long Fall is 35m high", "Located on Tai Mo Shan", "Near Kadoorie Farm area"],
      es: ["Conjunto de cuatro cascadas", "Long Fall tiene 35 m de altura", "Ubicación en el Tai Mo Shan", "Parte de los terrenos de Kadoorie"],
      pt: ["Conjunto de quatro quedas de água", "Long Fall tem 35 m de altura", "Localização no Tai Mo Shan", "Parte do terreno de Kadoorie"],
      fr: ["Ensemble de quatre cascades", "Long Fall mesure 35 m de haut", "Situation sur le Tai Mo Shan", "Fait partie du domaine de Kadoorie"],
    },
    imageHint: "Ng Tung Chai Long Fall waterfall",
    descriptionAdvanced: {
      de: "Die Ng Tung Chai Wasserfälle bieten eine spektakuläre Naturkulisse an den bewaldeten Nordhängen des Tai Mo Shan, dem höchsten Gipfel Hongkongs. Diese Kaskade besteht aus vier aufeinanderfolgenden Fällen: dem unteren Fall, dem mittleren Fall, dem beeindruckenden Long Fall und dem verstreuten Fall. Besonders der Long Fall ist mit seinen 35 Metern Höhe ein markantes Highlight der Region und stürzt senkrecht über eine steile Felswand. Der Wanderweg zu den Fällen führt durch dichten subtropischen Dschungel und vorbei an den Anlagen der Kadoorie Farm and Botanic Garden, die sich dem Naturschutz verschrieben hat. Die Umgebung ist geprägt von einer hohen Biodiversität, wobei die feuchten Felsen ideale Bedingungen für seltene Farne und Moose bieten. Während der Monsunzeit schwellen die Wassermassen stark an und verwandeln das Tal in ein tosende Naturschauspiel. Für Besucher stellt die Wanderung eine willkommene Abkühlung zur urbanen Hitze der Stadt dar, da die dichte Vegetation und das fließende Wasser für ein deutlich milderes Kleinklima sorgen.",
      hu: "Az Ng Tung Chai-vízesések Hongkong legmagasabb csúcsa, a Tai Mo Shan északi lejtőin találhatók, sűrű szubtrópusi erdők ölelésében. Ez a természeti látványosság négy egymást követő vízesésből áll: az Alsó-, a Középső-, a látványos Hosszú- és a Szórt-esésből. Ezek közül a 35 méter magas Hosszú-esés a legimpozánsabb, amely egy függőleges sziklafalról zúdul alá a mélybe. A vízesésekhez vezető túraútvonal érinti a Kadoorie Farm és Botanikus Kert területét, amely a régió természetvédelmi törekvéseinek központja. A párás környezet kedvez a ritka páfrányoknak és moháknak, a terület biodiverzitása pedig egyedülálló a környéken. Az esős évszakban a víztömeg jelentősen megnő, dübörgő hanggal töltve meg a völgyet. A látogatók számára ez a helyszín tökéletes menekülést kínál Hongkong városi forgatagából, ahol a kristálytiszta patakok és a hűvös erdei levegő frissítő élményt nyújtanak. A túra némi állóképességet igényel a meredek szakaszok miatt, de a látvány kárpótol minden fáradságért.",
      ro: "Cascadele Ng Tung Chai reprezintă una dintre cele mai spectaculoase atracții naturale din Hong Kong, fiind ascunse pe versanții nordici ai muntelui Tai Mo Shan. Această serie de căderi de apă cuprinde patru cascade distincte: Cascada Inferioară, Cascada Mijlocie, Cascada Long (cea mai înaltă, cu 35 de metri) și Cascada Răspândită. Traseul montan care le unește trece prin păduri tropicale dense și se află în apropierea Fermei și Grădinii Botanice Kadoorie, un centru important pentru conservarea speciilor locale. Mediul umed creat de căderile de apă favorizează o biodiversitate bogată, fiind habitatul ideal pentru diverse specii de ferigi și mușchi rari. În timpul sezonului ploios, debitul cascadelor crește considerabil, oferind un spectacol auditiv și vizual de o forță impresionantă. Pentru călători, o drumeție aici este o modalitate excelentă de a evada din aglomerația urbană, oferind un microclimat răcoros chiar și în zilele toride de vară. Drumul este presărat cu puncte de observare și bazine naturale unde apa cristalină invită la relaxare.",
      en: "Nestled on the lush northern slopes of Tai Mo Shan, Hong Kong's highest peak, the Ng Tung Chai Waterfalls offer a breathtaking escape into nature. This scenic series consists of four primary cascades: the Bottom Fall, Middle Fall, the towering Long Fall, and the Scattered Fall. At 35 meters in height, the Long Fall is the most spectacular, plunging vertically over a sheer rock face into a serene pool below. The hiking trail leading to these falls winds through dense subtropical forest and past the Kadoorie Farm and Botanic Garden, a renowned conservation facility. The constant mist from the falls creates a humid microclimate that supports an array of rare ferns, mosses, and diverse wildlife. During the monsoon season, the waterfalls transform into powerful torrents, filling the valley with a thunderous roar. For those looking to escape the city's concrete jungle, Ng Tung Chai provides a refreshing environment with much cooler temperatures than the urban areas. The trek is challenging but rewarding, showcasing the wild and untamed side of the territory.",
      es: "Las cataratas de Ng Tung Chai son una serie de cuatro saltos de agua en el Parque Rural Tai Mo Shan, cerca de la montaña más alta de Hong Kong (957 m). El agua cae sobre rocas de granito formando varias pozas. La catarata superior, conocida como 'Main Fall', es la más alta con 35 m. Las otras se denominan 'Middle Fall', 'Lower Fall' y 'Bottom Fall'. El volumen de agua varía estacionalmente; en época de lluvias, la cascada puede alcanzar los 10 m de ancho. El camino atraviesa una densa selva subtropical con más de 1000 especies de plantas. Se las conoce también como 'cascadas de tierras bajas', ya que se encuentran a solo 300 m de altitud.",
      pt: "As cataratas de Ng Tung Chai são uma cascata de quatro quedas de água no Parque Rural de Tai Mo Shan, perto da montanha mais alta de Hong Kong (957 m). As águas precipitam-se sobre rochas de granito e formam várias bacias. A queda superior, a 'Main Fall', é a mais alta com 35 m. As outras chamam-se 'Middle Fall', 'Lower Fall' e 'Bottom Fall'. O volume de água varia fortemente conforme a estação; durante a época das chuvas, a queda pode atingir 10 m de largura. O caminho para as cataratas atravessa uma densa floresta tropical com mais de 1000 espécies de plantas. São também designadas 'cataratas de terras baixas', por estarem a apenas 300 m de altitude.",
      fr: "Les cascades de Ng Tung Chai sont une succession de quatre chutes d'eau dans le parc rural de Tai Mo Shan, à proximité du plus haut sommet de Hong Kong (957 m). Les eaux se jettent sur des rochers de granit et forment plusieurs bassins. La chute supérieure, la 'Main Fall', est la plus haute avec 35 m. Les autres sont nommées 'Middle Fall', 'Lower Fall' et 'Bottom Fall'. Le débit d'eau varie fortement selon les saisons ; pendant la saison des pluies, la cascade peut atteindre 10 m de large. Le sentier menant aux cascades traverse une forêt tropicale dense abritant plus de 1000 espèces de plantes. Elles sont également appelées 'cascades de plaine', car elles ne se situent qu'à 300 m d'altitude.",
    },
