      fr: ["Nombre de cascades : 4", "Hauteur de la cascade principale : 35 m", "Altitude de la zone : 300 m", "Largeur pendant la saison des pluies : jusqu'à 10 m", "Sommet le plus proche : Tai Mo Shan (957 m)", "Espèces végétales dans la forêt environnante : plus de 1000"],
