    imageHint: "Bride's Pool waterfall scenery",
    descriptionAdvanced: {
      de: "Der Bride's Pool im Plover Cove Country Park ist einer der idyllischsten Naturorte in den New Territories von Hongkong. Er ist bekannt für seine kaskadenartigen Wasserfälle, die in ein tiefes, von Felsen umschlossenes Becken stürzen. Der Name des Ortes leitet sich von einer tragischen lokalen Legende ab: Eine Braut wurde in ihrer Sänfte zu ihrer Hochzeit getragen, als einer der Träger auf den glitschigen Steinen ausrutschte und sie in den Pool stürzte, wo sie aufgrund ihres schweren Hochzeitsgewandes ertrank. Trotz dieser melancholischen Geschichte ist der Ort heute ein äußerst beliebter Treffpunkt für Wanderer und Familien, die hier die kühle Waldluft und das Rauschen des Wassers genießen. Ein gut ausgebauter Naturlehrpfad führt zum Pool und zum nahe gelegenen Mirror Pool, einem weiteren beeindruckenden Wasserfall. Die Umgebung ist geprägt von dichter subtropischer Vegetation und bizarren Felsformationen, die im Kontrast zur urbanen Skyline der Stadt stehen. Es ist ein idealer Ort für Picknicks und Naturfotografie, besonders nach Regenfällen, wenn die Wasserfälle ihre volle Pracht entfalten.",
      hu: "A Plover Cove Park területén található Bride's Pool Hongkong Új területeinek egyik legfestőibb természeti látnivalója. A hely híres többlépcsős vízeséséről, amely egy mély, sziklákkal körülvett medencébe zúdul le. A név egy szomorú helyi legendából ered: a történet szerint egy menyasszonyt vittek a gyaloghintóján az esküvőjére, amikor az egyik hordár megcsúszott a vizes köveken, és a lány a vízbe esett, ahol nehéz esküvői ruhája miatt megfulladt. A melankolikus legenda ellenére a hely ma a kirándulók és családok kedvelt célpontja, akik a hűvös erdei levegő és a víz csobogása miatt látogatnak ide. Egy jól jelzett tanösvény vezet a medencéhez és a közeli Mirror Poolhoz, amely egy másik lenyűgöző vízesés. A környezetet dús szubtrópusi növényzet és különleges sziklaformációk jellemzik, amelyek tökéletes ellentétet mutatnak Hong Kong felhőkarcolóival. Ideális helyszín piknikezésre és természetfotózásra, különösen esőzések után, amikor a vízesések teljes erejükben pompáznak.",
      ro: "Bride's Pool, situat în Plover Cove Country Park, este unul dintre cele mai idilice locuri naturale din Noile Teritorii ale Hong Kong-ului. Este renumit pentru cascadele sale spectaculoase care se varsă într-un bazin adânc înconjurat de stânci. Numele locației provine dintr-o legendă locală tragică: se spune că o mireasă era transportată în lectica sa spre nuntă când unul dintre purtători a alunecat pe pietrele ude, iar tânăra a căzut în apă și s-a înecat din cauza greutății hainelor sale festive. În ciuda acestei povești melancolice, locul este astăzi o destinație populară pentru excursioniști și familii care vin să se bucure de aerul curat al pădurii și de sunetul relaxant al apei. Un traseu bine marcat duce către bazin și către cascada vecină, Mirror Pool. Împrejurimile sunt dominate de o vegetație subtropicală densă și formațiuni stâncoase bizare, oferind un contrast puternic cu zgârie-norii din centrul orașului. Este un loc ideal pentru picnic și fotografie de natură, în special după ploi, când debitele cascadelor sunt maxime.",
      en: "Bride's Pool, located within the Plover Cove Country Park, is one of the most picturesque natural attractions in Hong Kong's New Territories. It is famous for its series of cascading waterfalls that plunge into a deep pool enclosed by sheer rock faces. The site's name is rooted in a somber local legend: a bride was being carried in her sedan chair to her wedding when one of the porters slipped on the wet rocks, causing her to fall into the pool where she tragically drowned due to her heavy traditional garments. Despite its melancholic backstory, the area is a beloved destination for hikers and families seeking the cool forest air and the soothing sound of rushing water. A well-maintained nature trail leads visitors to the pool and the nearby Mirror Pool, another impressive waterfall. The surrounding landscape features lush subtropical vegetation and unique geological formations, providing a sharp contrast to Hong Kong's urban skyline. It is an ideal spot for picnicking and nature photography, especially after rainfall when the falls are at their most powerful.",
      es: "El Bride's Pool es un estanque natural en el Plover Cove Country Park, alimentado por una cascada. El nombre proviene de una leyenda local según la cual una novia se ahogó de camino a su boda. El estanque tiene unos 10 m de ancho y 3 m de profundidad, rodeado de una vegetación exuberante. Cerca se encuentran varias cascadas menores y la 'Bride's Pool Road'. La zona es un destino popular para picnics y exploraciones naturales. La formación geológica consiste en arenisca y conglomerado del Jurásico. El estanque está a una altura de unos 150 m y se accede por un corto sendero.",
      pt: "O Bride's Pool é uma lagoa natural no Plover Cove Country Park, alimentada por uma cascata. O nome deriva de uma lenda local, segundo a qual uma noiva se teria afogado a caminho do seu casamento. A lagoa tem cerca de 10 m de largura e 3 m de profundidade, rodeada por vegetação exuberante. Nas proximidades encontram-se várias cascatas menores e a 'Bride's Pool Road'. A área é um destino popular para piqueniques e explorações naturais. A formação geológica consiste em arenito e conglomerado do Jurássico. A lagoa situa-se a uma altitude de cerca de 150 m e é acessível através de um curto trilho.",
      fr: "Le Bride's Pool est un bassin naturel situé dans le Plover Cove Country Park, alimenté par une cascade. Son nom provient d'une légende locale selon laquelle une mariée se serait noyée en se rendant à son mariage. Le bassin mesure environ 10 m de large et 3 m de profondeur, entouré d'une végétation luxuriante. À proximité se trouvent plusieurs cascades plus petites et la 'Bride's Pool Road'. Le site est une destination populaire pour les pique-niques et l'exploration de la nature. La formation géologique se compose de grès et de conglomérat du Jurassique. Le bassin est situé à une altitude d'environ 150 m et est accessible par un court sentier de randonnée.",
    },
