    imageHint: "Sharp Island tombolo at low tide",
    descriptionAdvanced: {
      de: "Sharp Island, lokal als Kiu Tsui Chau bekannt, ist eines der geologischen Highlights im UNESCO Global Geopark von Hongkong. Die Insel ist berühmt für ihren natürlichen Tombolo, eine etwa 250 Meter lange Sand- und Kiesbank, die nur bei Ebbe sichtbar wird und die Hauptinsel mit dem nahegelegenen Kiu Tau Islet verbindet. Ein Spaziergang über diesen Pfad ist ein Muss für Naturfreunde, erfordert jedoch eine genaue Planung nach dem Gezeitenkalender. Geologisch ist die Insel faszinierend aufgrund der „Ananas-Brot-Felsen“ – Quarz-Monzonit-Steine, deren Oberfläche durch Verwitterung so stark rissig geworden ist, dass sie an die Kruste des typischen Hongkonger Gebäcks erinnern. Neben den geologischen Formationen bietet Sharp Island mit den Stränden Hap Mun Bay und Kiu Tsui Beach kristallklares Wasser, das ideal zum Schnorcheln und Schwimmen ist. Die Unterwasserwelt beherbergt eine erstaunliche Vielfalt an Korallen und Fischen, was die Insel zu einem beliebten Rückzugsort vom hektischen Stadtleben macht.",
      hu: "A Kiu Tsui Chau néven is ismert Sharp-sziget Hongkong egyik legkülönlegesebb természeti kincse, amely az UNESCO Globális Geopark részét képezi. Legismertebb vonzereje a természetes tomboló: egy körülbelül 250 méter hosszú, homokból és kavicsokból álló gát, amely csak apály idején bukkan elő, összekötve a főszigetet a Kiu Tau nevű apró szigettel. A látogatóknak érdemes figyelniük az árapály-táblázatot, hogy biztonságosan átkelhessenek ezen a különleges földnyelven. A sziget geológiai érdekességei közé tartoznak az úgynevezett „ananász-zsemle sziklák”. Ezek a kvarc-monzonit kőzetek a természetes erózió és mállás következtében kaptak olyan repedezett felületet, amely kísértetiesen emlékeztet a népszerű hongkongi péksütemény külsejére. A természetjárók mellett a strandolók is kedvelik a helyet; a Hap Mun Bay és a Kiu Tsui Beach kristálytiszta vize kiváló lehetőséget nyújt sznorkelezésre és úszásra, ahol a korallok és a színes tengeri élővilág közvetlen közelről megfigyelhető.",
      ro: "Insula Sharp, cunoscută local sub numele de Kiu Tsui Chau, este o bijuterie geologică situată în cadrul Geoparcului Global UNESCO din Hong Kong. Principala sa atracție este un tombolo natural spectaculos, o fâșie de nisip și pietriș lungă de aproximativ 250 de metri care apare doar în timpul refluxului, făcând legătura între insula principală și micul ostrov Kiu Tau. Turiștii trebuie să consulte cu atenție tabelul mareelor pentru a traversa în siguranță acest drum efemer. Din punct de vedere geologic, insula este faimoasă pentru rocile sale în formă de „pâine cu ananas” (Pineapple Bun Rocks). Aceste formațiuni din monzonit cuarțos au suprafețe crăpate din cauza eroziunii diferențiale, semănând izbitor cu textura produsului de patiserie tradițional din Hong Kong. Pe lângă aspectele geologice, Insula Sharp oferă plaje cu apă extrem de limpede, precum Hap Mun Bay și Kiu Tsui Beach, fiind destinații preferate pentru snorkeling datorită biodiversității marine și a recifelor de corali bine conservate.",
      en: "Sharp Island, also known as Kiu Tsui Chau, is a prominent feature of the Hong Kong UNESCO Global Geopark, located just a short boat ride from Sai Kung. The island’s most iconic landmark is its 250-meter-long natural tombolo, a sand and gravel levee that connects the main island to the smaller Kiu Tau islet during low tide. Visitors often time their trips specifically to walk across this tidal bridge, exploring the diverse coastal ecology along the way. Geologically, the island is renowned for its unique igneous rocks, particularly the \"pineapple bun rocks.\" These weathered boulders of quartz monzonite feature a distinctive cracked surface caused by thermal expansion and contraction, resembling the crust of a local Hong Kong pastry. Beyond its geological wonders, Sharp Island boasts some of the cleanest waters in the territory. Hap Mun Bay and Kiu Tsui Beach are popular spots for swimming and snorkeling, offering a chance to see vibrant coral communities and various fish species in a pristine natural setting.",
      es: "Sharp Island (isla Kiu Tsui) se encuentra en Port Shelter, a unos 2 km de Sai Kung. Tiene una superficie de aproximadamente 6,7 km² y se une con la vecina isla Kiu Tau mediante un tómbolo (un estrecho banco de arena) que aparece con la marea baja. Destacan la 'Cueva de los Monstruos' (una cueva marina) y la 'Roca Piña', una peculiar formación de granito. Antiguamente era un cabo, pero el ascenso del nivel del mar la convirtió en isla. Ofrece playas y senderos. Aunque está deshabitada, es muy popular entre excursionistas. Las aguas circundantes son una reserva marina con más de 60 especies de corales.",
      pt: "Sharp Island (ilha de Kiu Tsui) situa-se no Port Shelter, a cerca de 2 km de Sai Kung. A ilha tem uma área de cerca de 6,7 km² e liga-se à ilha vizinha de Kiu Tau por um tómbolo durante a maré baixa. Destacam-se a 'Monster Cave' (gruta marinha) e a 'Pineapple Rock' (rocha ananás) – uma curiosa formação de granito. A ilha era anteriormente um cabo, mas tornou-se ilha devido à subida do nível do mar. Existem praias e trilhos. A ilha é desabitada, mas popular entre excursionistas. As águas circundantes são uma reserva marinha com mais de 60 espécies de corais.",
      fr: "Sharp Island (île de Kiu Tsui) est située dans le Port Shelter, à environ 2 km de Sai Kung. L'île couvre une superficie d'environ 6,7 km² et est reliée à l'île voisine de Kiu Tau par un tombolo (un banc de sable étroit) à marée basse. On y trouve la 'Grotte aux Monstres' (une grotte marine) et le 'Rocher d'Ananas', une formation granitique singulière. Autrefois un promontoire, elle est devenue une île suite à l'élévation du niveau de la mer. Elle propose des plages et des sentiers de randonnée. Bien qu'inhabitée, elle est prisée des excursionnistes. Les eaux environnantes forment une réserve marine abritant plus de 60 espèces de coraux.",
    },
