    parent: "HK",
    type: "mountain",
    name: { de: "Pat Sin Leng", hu: "Pat Sin Leng", ro: "Pat Sin Leng", en: "Pat Sin Leng" },
    coords: [114.2167, 22.4833],
    description: {
      de: "Pat Sin Leng ist eine Kette von acht Gipfeln im Nordosten von Hongkong. Der Name bedeutet 'Kamm der acht Unsterblichen' nach Figuren der chinesischen Mythologie.",
      hu: "A Pat Sin Leng egy nyolc csúcsból álló hegylánc Hongkong északkeleti részén. Neve a 'nyolc halhatatlan gerincét' jelenti a kínai mitológiából.",
      ro: "Pat Sin Leng este un lanț de opt vârfuri în nord-estul Hong Kong-ului. Numele înseamnă 'Creasta celor Opt Nemuritori'.",
      en: "Pat Sin Leng is a range of eight peaks in northeast Hong Kong. Its name means 'Ridge of the Eight Immortals' from Chinese mythology.",
      es: "Pat Sin Leng es una cadena de ocho picos en el noreste de Hong Kong. Su nombre significa 'Cresta de los Ocho Inmortales' en honor a personajes de la mitología china.",
      pt: "Pat Sin Leng é uma cadeia de oito picos no nordeste de Hong Kong. O nome significa 'Crista dos Oito Imortais', em homenagem a figuras da mitologia chinesa.",
      fr: "Pat Sin Leng est une chaîne de huit sommets située au nord-est de Hong Kong. Son nom signifie 'Crête des Huit Immortels', d'après des personnages de la mythologie chinoise.",
    },
    facts: {
      de: ["Kette aus acht Gipfeln", "Höchster Gipfel: Shun Yeung", "Blick auf Plover Cove", "Name aus der Mythologie"],
      hu: ["Nyolc csúcsból álló lánc", "Legmagasabb pont: Shun Yeung", "Kilátás a Plover Cove-ra", "Mitológiai eredetű név"],
      ro: ["Lanț de opt vârfuri", "Vârful Shun Yeung (590m)", "Vedere spre Plover Cove", "Nume din mitologie"],
      en: ["Chain of eight peaks", "Highest peak: Shun Yeung", "Views of Plover Cove", "Name from Chinese mythology"],
      es: ["Cadena de ocho picos", "Pico más alto: Shun Yeung", "Vistas a Plover Cove", "Nombre de origen mitológico"],
      pt: ["Cadeia de oito picos", "Pico mais alto: Shun Yeung", "Vista para Plover Cove", "Nome da mitologia"],
      fr: ["Chaîne de huit sommets", "Sommet le plus élevé : Shun Yeung", "Vue sur Plover Cove", "Nom issu de la mythologie"],
    },
    imageHint: "Pat Sin Leng eight peaks range",
    descriptionAdvanced: {
      de: "Pat Sin Leng ist eine markante Bergkette im Nordosten von Hongkong, die für ihre acht markanten Gipfel bekannt ist. Der Name stammt aus der chinesischen Mythologie und bedeutet 'Kamm der acht Unsterblichen', wobei jeder Gipfel nach einer dieser legendären Figuren benannt wurde. Der höchste Punkt der Kette ist der Shun Yeung Peak mit einer Höhe von 590 Metern. Eine Wanderung über diesen Grat gilt als anspruchsvoll, belohnt jedoch mit einigen der spektakulärsten Aussichten in den New Territories, darunter Panoramen über den Plover Cove Stausee und bis hinüber nach Shenzhen in China. Das Gebiet liegt innerhalb des Pat Sin Leng Country Parks und bietet eine unberührte Naturkulisse, die weit entfernt vom geschäftigen Stadtleben Hongkongs liegt. Die Region ist auch historisch bedeutsam und erinnert an die Gefahren von Buschfeuern, was durch das dortige Denkmal für verstorbene Wanderer und Retter unterstrichen wird.",
      hu: "A Pat Sin Leng egy drámai megjelenésű hegylánc Hongkong északkeleti részén, amely nyolc különálló csúcsból áll. A név a kínai mitológiából ered, jelentése a „nyolc halhatatlan gerince”, ahol minden egyes csúcsot az egyik legendás alakról neveztek el. A legmagasabb pont a Shun Yeung-csúcs, amely 590 méterrel magasodik a tengerszint fölé. A hegyláncon végighúzódó túraútvonal Hongkong egyik legnehezebb, de leglátványosabb gerinctúrája, ahonnan páratlan kilátás nyílik a Plover Cove víztározóra, a Tolo-öbölre és tiszta időben egészen a kínai Sencsen városáig el lehet látni. A terület a Pat Sin Leng Country Park része, ahol a látogatók megtapasztalhatják az Új Területek vadregényes, érintetlen természetét. A túra során a vándoroknak számos meredek emelkedőt és ereszkedőt kell leküzdeniük, így a felkészült és kitartó kirándulók számára ajánlott ez a mitológiai hangulatú vidék.",
      ro: "Pat Sin Leng este un lanț muntos impresionant situat în nord-estul Hong Kong-ului, renumit pentru cele opt vârfuri ale sale care formează o linie zimțată pe orizont. Numele se traduce prin „Creasta celor Opt Nemuritori”, fiecare vârf fiind dedicat unei figuri legendare din mitologia chineză. Cel mai înalt punct este vârful Shun Yeung, atingând 590 de metri. Traseul care parcurge întreaga creastă este considerat unul dintre cele mai solicitante din teritoriu, necesitând o condiție fizică bună pentru a naviga succesiunea rapidă de urcări și coborâri. Recompensa este însă pe măsură: vederi panoramice uluitoare asupra lacului de acumulare Plover Cove și a golfului Tolo, oferind o perspectivă rară asupra peisajului rural din New Territories. Inclus în parcul național cu același nume, Pat Sin Leng este o destinație de top pentru drumeții care caută aventură și conexiune cu tradițiile spirituale ale regiunii, departe de aglomerația urbană.",
      en: "Pat Sin Leng is a striking mountain range in northeast Hong Kong, famous for its jagged skyline consisting of eight distinct peaks. The name, meaning 'Ridge of the Eight Immortals', draws from Chinese mythology, with each summit named after a different immortal figure. The highest point is Shun Yeung Peak, standing at 590 meters. Hiking across this ridge is widely regarded as one of the most challenging treks in the New Territories due to the continuous sequence of steep climbs and descents across all eight summits. However, it offers unparalleled panoramic views of Plover Cove Reservoir, Tolo Harbour, and even the skyline of Shenzhen across the border on clear days. Located within the Pat Sin Leng Country Park, the area is a haven for biodiversity and rugged natural beauty. It serves as a reminder of the wilder side of Hong Kong, providing a spiritual and physical challenge for experienced hikers seeking to conquer these legendary slopes.",
      es: "Pat Sin Leng (Cresta de los Ocho Inmortales) es una cadena montañosa de 8 km en el noreste de los Nuevos Territorios. La cresta consta de ocho picos nombrados en honor a los ocho inmortales de la mitología taoísta. El punto más alto es el Wong Leng (639 m). La cordillera forma parte del Parque Rural Pat Sin Leng. La región destaca por su variada flora, que incluye orquídeas y rododendros. El Pat Sin Leng Nature Trail, un sendero educativo de 4,5 km, ofrece información sobre la ecología local. La cresta se encuentra en la cuenca del embalse de Plover Cove y es popular entre senderistas por sus vistas panorámicas de Tolo Harbour y la frontera con China.",
      pt: "Pat Sin Leng (Crista dos Oito Imortais) é uma cadeia montanhosa de 8 km no nordeste dos Novos Territórios. A crista é composta por oito picos batizados com o nome dos oito imortais da mitologia taoista. O pico mais alto é o Wong Leng (639 m). A cadeia faz parte do Parque Rural de Pat Sin Leng. A região é conhecida pela sua flora diversificada, incluindo orquídeas e rododendros. O Trilho Natural de Pat Sin Leng, com 4,5 km, fornece informações sobre a ecologia local. A crista situa-se na bacia hidrográfica do reservatório de Plover Cove e oferece vistas panorâmicas sobre o Tolo Harbour e a fronteira com a China.",
      fr: "Pat Sin Leng (Crête des Huit Immortels) est une chaîne de montagnes de 8 km située au nord-est des Nouveaux Territoires. Elle se compose de huit pics nommés d'après les huit immortels de la mythologie taoïste. Le point culminant est le Wong Leng (639 m). La chaîne fait partie du parc rural de Pat Sin Leng. La région est réputée pour sa flore variée, notamment ses orchidées et ses rhododendrons. Le Pat Sin Leng Nature Trail, un sentier éducatif de 4,5 km, informe sur l'écologie locale. La crête se trouve dans le bassin versant du réservoir de Plover Cove et offre des vues panoramiques sur Tolo Harbour et la frontière chinoise.",
    },
