      en: ["Ridge length: 8 km", "Number of peaks: 8", "Highest peak: Wong Leng (639 m)", "Nature trail length: 4.5 km", "Part of Pat Sin Leng Country Park (established 1979)", "Flora: over 500 plant species documented"],
