      ro: ["Ape foarte calme", "Roci sedimentare roșii", "Destinație pentru navigație", "Cuprinde mai multe insule"],
      en: ["Very calm waters", "Red sedimentary rocks", "Popular for sailing", "Includes several islands"],
      es: ["Aguas extremadamente tranquilas", "Rocas sedimentarias rojas", "Popular zona de navegación", "Incluye varias islas"],
