      de: "Der Kam Shan Country Park wird oft als 'Monkey Hill' bezeichnet, da dort eine große Population von Makaken lebt. Er umfasst mehrere historische Reservoirs.",
      hu: "A Kam Shan Parkot gyakran 'Majom-dombnak' hívják a hatalmas makákó populáció miatt. Több történelmi víztározót foglal magában.",
      ro: "Parcul Kam Shan este numit adesea 'Monkey Hill' din cauza populației mari de macaci. Cuprinde rezervoare istorice.",
      en: "Kam Shan Country Park is often called 'Monkey Hill' due to its large population of macaques. It encompasses several historic reservoirs.",
      es: "El Parque Rural Kam Shan es a menudo llamado 'Monkey Hill' debido a su gran población de macacos. Incluye varios embalses históricos.",
      pt: "O Parque Rural Kam Shan é frequentemente chamado de 'Monkey Hill', pois abriga uma grande população de macacos. Inclui vários reservatórios históricos.",
