    imageHint: "Tai Tam Tuk Reservoir stone bridge",
    descriptionAdvanced: {
      de: "Das Tai Tam Tuk Reservoir wurde 1917 fertiggestellt und war die letzte und ehrgeizigste Phase des Tai Tam-Wasserwerkprojekts, das den wachsenden Wasserbedarf des frühen 20. Jahrhunderts in Hongkong decken sollte. Dieses Meisterwerk der Ingenieurskunst ist besonders berühmt für seine zwölf Granit-Bogenbrücken, die mit ihren eleganten Strukturen noch heute den lokalen Verkehr tragen. Diese Bauwerke wurden zusammen mit dem gewaltigen Hauptdamm und dem historischen Pumpwerk aufgrund ihres außergewöhnlichen architektonischen und historischen Wertes zu geschützten Denkmälern erklärt. Der Stausee ist von üppigem Grün umgeben und ein beliebtes Ziel für Wanderer und Fotografen, die das Spiegelbild der Brücken im edwardianischen Stil im klaren Wasser einfangen möchten. Während der Regenzeit erzeugt der Überlauf des Damms einen dramatischen Wasserfalleffekt, der viele Besucher anzieht, um die schiere Größe dieser perfekt erhaltenen kolonialen Infrastruktur zu bewundern.",
      hu: "A Tai Tam Tuk-víztározó 1917-ben készült el, és ez volt a Tai Tam vízellátó rendszer utolsó és legjelentősebb szakasza, amely a 20. század elején dinamikusan növekvő Hong Kong igényeit szolgálta ki. Ez a mérnöki bravúr elsősorban a tizenkét kőíves hídjáról híres, amelyek gránitból készültek, és máig fontos szerepet töltenek be a helyi közlekedésben. Ezeket az építményeket a főgáttal és a történelmi szivattyúházzal együtt hivatalosan is műemlékké nyilvánították kiemelkedő építészeti és történeti értékük miatt. A tározót buja növényzet veszi körül, így a természetjárók és fotósok kedvelt célpontja, akik szívesen örökítik meg az edwardi stílusú hidak tükröződését a tiszta vízfelületen. Az esős évszakban a gát túlfolyója látványos vízesést hoz létre, ami még több látogatót vonz, hogy megcsodálják a gyarmati korszak infrastruktúrájának ezt a grandiózus és épségben maradt darabját.",
      ro: "Rezervorul Tai Tam Tuk, finalizat în anul 1917, reprezintă ultima și cea mai ambițioasă etapă a schemei de alimentare cu apă Tai Tam, fiind esențial pentru dezvoltarea insulei Hong Kong la începutul secolului XX. Acest complex de inginerie hidraulică este renumit în special pentru cele douăsprezece poduri din zidărie de granit, construite cu arcuri elegante care susțin și astăzi traficul rutier local. Structurile, împreună cu barajul principal masiv și stația de pompare istorică, au fost declarate monumente protejate datorită valorii lor arhitecturale și tehnice excepționale. Rezervorul este înconjurat de o vegetație luxuriantă, fiind o destinație preferată pentru excursioniști și fotografi care doresc să surprindă reflexia podurilor în stil edwardian în apele limpezi. În timpul sezonului ploios, deversorul barajului creează o cascadă spectaculoasă, atrăgând numeroși vizitatori care vin să admire amploarea acestei infrastructuri coloniale perfect conservate.",
      en: "Tai Tam Tuk Reservoir, completed in 1917, was the final and most ambitious phase of the Tai Tam Waterworks Scheme, designed to meet the growing water demands of early 20th-century Hong Kong. This engineering masterpiece is particularly famous for its twelve masonry bridges, constructed from granite with elegant arches that still carry local traffic today. These structures, along with the massive main dam and the historic pumping station, have been declared monuments due to their exceptional architectural and historical value. The reservoir is surrounded by lush greenery, making it a favorite destination for hikers and photographers who come to capture the reflection of the Edwardian-style bridges in the clear water. During the rainy season, the spillway of the dam creates a dramatic waterfall effect, attracting visitors to witness the sheer scale of this colonial-era infrastructure that remains in excellent condition.",
      es: "El Tai Tam Tuk Reservoir es un embalse en el Parque Rural de Tai Tam, en la isla de Hong Kong. Se terminó de construir en 1918 y forma parte del Sendero del Patrimonio de las Obras Hidráulicas de Tai Tam. El embalse tiene una capacidad de 19,5 millones de metros cúbicos y una superficie de agua de 0,9 km². La presa tiene 90 m de longitud y 30 m de altura. El bosque circundante sirve de hábitat a especies de aves raras como el monarca nuquinegro. El embalse se caracteriza por sus puentes históricos de piedra y el edificio de la presa de estilo victoriano. El Tai Tam Tuk Reservoir Walk es una ruta de senderismo de 4 km.",
      pt: "O Reservatório Tai Tam Tuk é um reservatório no Parque Rural de Tai Tam, na ilha de Hong Kong. Foi concluído em 1918 e faz parte do Trilho do Património das Obras Hidráulicas de Tai Tam. O reservatório tem uma capacidade de 19,5 milhões de metros cúbicos e uma superfície de água de 0,9 km². A barragem tem 90 m de comprimento e 30 m de altura. A floresta circundante oferece habitat para espécies de aves raras, como o monarca-de-nuca-preta. O reservatório é caracterizado por pontes de pedra históricas e um edifício de barragem vitoriano. O Tai Tam Tuk Reservoir Walk é um trilho de caminhada de 4 km.",
      fr: "Le réservoir de Tai Tam Tuk est un lac de barrage situé dans le parc de Tai Tam, sur l'île de Hong Kong. Achevé en 1918, il fait partie du sentier du patrimoine des installations hydrauliques de Tai Tam. Le réservoir a une capacité de 19,5 millions de mètres cubes et une surface d'eau de 0,9 km². Le barrage mesure 90 m de long et 30 m de haut. La forêt environnante abrite des espèces d'oiseaux rares comme le monarque azuré. Le réservoir se distingue par ses ponts historiques en pierre et son bâtiment de barrage victorien. Le Tai Tam Tuk Reservoir Walk est un sentier de randonnée de 4 km.",
    },
