      ro: ["Rezervație marină din: 1999", "Far construit: 1875", "Înălțimea farului: 12 m", "Formațiuni geologice: Stânca Leului, Peștera Sirenei", "Parte a Parcului Rural Shek O", "Distanța până la cea mai apropiată stație de autobuz: 1,5 km"],
      en: ["Marine reserve since: 1999", "Lighthouse built: 1875", "Lighthouse height: 12 m", "Geological formations: Lion Rock, Mermaid Cave", "Part of Shek O Country Park", "Distance to nearest bus stop: 1.5 km"],
      es: ["Protección marina desde: 1999", "Faro construido en: 1875", "Altura del faro: 12 m", "Formaciones geológicas: Roca del León, Cueva de la Sirena", "Parte del Parque Rural Shek O", "Distancia a la parada de bus: 1,5 km"],
      pt: ["Área marinha protegida desde: 1999", "Farol construído em: 1875", "Altura do farol: 12 m", "Formações geológicas: Rocha do Leão, Gruta da Sereia", "Parte do Shek O Country Park", "Distância até à paragem de autocarro: 1,5 km"],
      fr: ["Zone de protection marine depuis : 1999", "Phare construit en : 1875", "Hauteur du phare : 12 m", "Formations géologiques : Rocher du Lion, Grotte de la Sirène", "Fait partie du Shek O Country Park", "Distance de l'arrêt de bus : 1,5 km"],
