      es: ["Altura de 468 metros", "Terreno muy empinado", "Emblema de Sai Kung", "Ruta de senderismo difícil"],
      pt: ["Altitude de 468 metros", "Terreno muito íngreme", "Ponto de referência de Sai Kung", "Trilho de caminhada difícil"],
      fr: ["Altitude de 468 mètres", "Terrain très escarpé", "Emblème de Sai Kung", "Sentier de randonnée difficile"],
