      hu: ["Magasság: 468 m", "Hely: Sai Kung East Country Park", "A MacLehose Trail 2. szakaszának része (hossz: 14 km)", "Emelkedési idő Sai Wanból: 3-4 óra", "Geológia: vulkanikus kőzet (jura)", "Legközelebbi strand: Sai Wan (1,5 km)"],
      ro: ["Înălțime: 468 m", "Locație: Parcul Rural Sai Kung East", "Parte a traseului MacLehose Stage 2 (lungime: 14 km)", "Timp de ascensiune de la Sai Wan: 3-4 ore", "Geologie: rocă vulcanică (Jurasic)", "Cea mai apropiată plajă: Sai Wan (1,5 km)"],
      en: ["Elevation: 468 m", "Location: Sai Kung East Country Park", "Part of MacLehose Trail Stage 2 (length: 14 km)", "Ascent time from Sai Wan: 3-4 hours", "Geology: volcanic rock (Jurassic)", "Nearest beach: Sai Wan (1.5 km)"],
      es: ["Altura: 468 m", "Ubicación: Parque Rural Sai Kung East", "Parte del MacLehose Trail Etapa 2 (longitud: 14 km)", "Tiempo de ascenso desde Sai Wan: 3-4 horas", "Geología: roca volcánica (Jurásico)", "Playa más cercana: Sai Wan (1,5 km)"],
      pt: ["Altitude: 468 m", "Localização: Parque Rural de Sai Kung East", "Parte do MacLehose Trail Etapa 2 (extensão: 14 km)", "Tempo de subida desde Sai Wan: 3-4 horas", "Geologia: rocha vulcânica (Jurássico)", "Praia mais próxima: Sai Wan (1,5 km)"],
      fr: ["Altitude : 468 m", "Localisation : Parc rural de Sai Kung East", "Fait partie du MacLehose Trail étape 2 (longueur : 14 km)", "Temps d'ascension depuis Sai Wan : 3-4 heures", "Géologie : roche volcanique (Jurassique)", "Plage la plus proche : Sai Wan (1,5 km)"],
