    imageHint: "Kowloon Peak city night view",
    descriptionAdvanced: {
      de: "Der Kowloon Peak, auch als Fei Ngo Shan bekannt, ragt 602 Meter über den Meeresspiegel und ist damit der markanteste Gipfel im Osten Kowloons. Wanderer schätzen den Aufstieg vor allem wegen des berüchtigten \"Suicide Cliff\", einem steilen Felsvorsprung, der einen fast senkrechten Blick auf die dichte Wolkenkratzerlandschaft von San Po Kong und Choi Hung bietet. Der Gipfel ist Teil des Ma On Shan Country Parks und dient als wichtiger Standort für Sendeanlagen. Besonders nach Sonnenuntergang ist der Berg ein Magnet für Fotografen, da sich von hier aus das glitzernde Lichtermeer Hongkongs bis hin zum Victoria Harbour erstreckt. Die Zufahrt über die Fei Ngo Shan Road ermöglicht es auch weniger ambitionierten Besuchern, die kühle Brise und die Panoramaaussicht weit abseits der hektischen Straßenschluchten zu genießen, während die umliegenden Wanderwege tief in die subtropische Vegetation des Gebirges führen.",
      hu: "A Kowloon-csúcs, helyi nevén Fei Ngo Shan, 602 méteres magasságával Kowloon legmagasabb pontja, amely drámai falként tornyosul a város fölé. A hegy legnevezetesebb pontja az északi oldalon található \"Öngyilkos-szikla\" (Suicide Cliff), amely nevét nem tragédiákról, hanem a szédítően meredek pereméről kapta, ahonnan lélegzetelállító kilátás nyílik a felhőkarcolók sűrűjére. A csúcs a Ma On Shan országos park része, és fontos távközlési központ, ahol számos adótorony található. Esténként a helyi lakosok és turisták kedvelt célpontja, mivel innen nyílik Hongkong egyik legátfogóbb panorámája, amely tiszta időben egészen a Victoria-kikötőig és a Hongkong-szigetig ér. A kanyargós Fei Ngo Shan úton megközelíthető kilátóhelyek tökéletes menedéket nyújtanak a városi nyüzsgés elől, miközben a túraútvonalak dús szubtrópusi növényzeten keresztül vezetnek a gerincre.",
      ro: "Vârful Kowloon, cunoscut local sub numele de Fei Ngo Shan, se ridică la o altitudine de 602 metri, fiind cel mai înalt punct din zona Kowloon a Hong Kong-ului. Muntele este faimos în rândul comunității de drumeții pentru \"Suicide Cliff\", o stâncă abruptă care oferă o perspectivă verticală spectaculoasă asupra cartierelor dens populate precum San Po Kong. Situat în cadrul parcului național Ma On Shan, vârful servește și ca punct strategic pentru numeroase turnuri de transmisie radio și televiziune. Vizitatorii aleg adesea să urce aici la lăsarea serii, când luminile orașului se aprind, creând un ocean strălucitor care se întinde până la Portul Victoria. Accesul se poate face atât pe poteci abrupte, cât și pe drumul asfaltat Fei Ngo Shan, care permite accesul vehiculelor până aproape de creastă, oferind o alternativă răcoroasă și liniștită la agitația urbană de la baza muntelui.",
      en: "Kowloon Peak, also known by its Cantonese name Fei Ngo Shan, stands at an elevation of 602 meters, making it the highest summit in the Kowloon area. The mountain is world-renowned for \"Suicide Cliff,\" a rugged rocky outcrop on its southern face that offers a dizzying, near-vertical perspective of the urban sprawl below, including San Po Kong and Choi Hung. As part of the Ma On Shan Country Park, it is a biodiversity hotspot and a critical site for telecommunication transmitters. Photographers and night-watchers frequent the summit because it provides one of the most comprehensive views of Hong Kong's skyline, stretching across the harbour to Hong Kong Island. Accessible via the winding Fei Ngo Shan Road or through challenging hiking trails, the peak serves as a dramatic natural backdrop to the city and a premier destination for those seeking to capture the scale of Hong Kong's vertical architecture.",
      es: "Kowloon Peak (Fei Ngo Shan), con 602 m, es la cima más alta de Kowloon. Ubicado en el Parque Rural Ma On Shan, ofrece vistas panorámicas de la isla de Hong Kong, el puerto Victoria y los Nuevos Territorios. La cumbre destaca por su radiofaro y la 'Suicide Wall', una ruta de escalada peligrosa. Es un destino predilecto para senderistas y practicantes de parapente. Su nombre significa 'Montaña del Ganso Volador'. La vegetación varía entre praderas y matorrales. Se accede por la etapa 4 del Wilson Trail y sus amaneceres son espectaculares.",
      pt: "O Pico de Kowloon (Fei Ngo Shan) é, com 602 m, a montanha mais alta de Kowloon. Localizado no Ma On Shan Country Park, oferece vistas panorâmicas da Ilha de Hong Kong, do Porto Victoria e dos Novos Territórios. O cume é conhecido pelo seu radiofarol e pela 'Suicide Wall', uma rota de escalada perigosa. A montanha é um destino popular para caminhantes e praticantes de parapente. O nome significa 'Montanha do Ganso Voador'. A vista é particularmente espetacular ao nascer do sol.",
      fr: "Le pic de Kowloon (Fei Ngo Shan) est, avec ses 602 m, le plus haut sommet de Kowloon. Situé dans le Ma On Shan Country Park, il offre un panorama sur l'île de Hong Kong, Victoria Harbour et les Nouveaux Territoires. Le sommet est connu pour son émetteur et le 'Suicide Wall', une voie d'escalade périlleuse. C'est un lieu prisé des randonneurs et des parapentistes. Son nom signifie 'Montagne de l'Oie Volante'. La vue est particulièrement spectaculaire au lever du soleil.",
    },
    factsAdvanced: {
      de: ["Höhe: 602 m", "Standort: Ma On Shan Country Park", "Teil des Wilson Trail Stage 4 (Länge: 12 km)", "Beacon-Höhe: 10 m", "Kletterroute 'Suicide Wall': Schwierigkeitsgrad 5.9", "Entfernung zum nächsten MTR: 3 km (Diamond Hill)"],
      hu: ["Magasság: 602 m", "Hely: Ma On Shan Country Park", "A Wilson Trail 4. szakaszának része (hossz: 12 km)", "Jeladó magassága: 10 m", "'Öngyilkos fal' mászóút: nehézségi fok 5.9", "Távolság a legközelebbi MTR-től: 3 km (Diamond Hill)"],
      ro: ["Înălțime: 602 m", "Locație: Parcul Rural Ma On Shan", "Parte a traseului Wilson Stage 4 (lungime: 12 km)", "Înălțimea farului: 10 m", "Ruta de alpinism 'Zidul sinucigașilor': grad de dificultate 5.9", "Distanța până la cel mai apropiat MTR: 3 km (Diamond Hill)"],
      en: ["Elevation: 602 m", "Location: Ma On Shan Country Park", "Part of Wilson Trail Stage 4 (length: 12 km)", "Beacon height: 10 m", "Climbing route 'Suicide Wall': difficulty 5.9", "Distance to nearest MTR: 3 km (Diamond Hill)"],
      es: ["Altura: 602 m", "Ubicación: Parque Rural Ma On Shan", "Parte del Wilson Trail Etapa 4 (12 km)", "Altura del radiofaro: 10 m", "Ruta 'Suicide Wall': grado de dificultad 5.9", "Distancia al MTR: 3 km (Diamond Hill)"],
      pt: ["Altitude: 602 m", "Localização: Ma On Shan Country Park", "Parte do Wilson Trail Etapa 4 (extensão: 12 km)", "Altura do radiofarol: 10 m", "Rota de escalada 'Suicide Wall': dificuldade 5.9", "Distância até ao MTR: 3 km (Diamond Hill)"],
      fr: ["Altitude : 602 m", "Lieu : Ma On Shan Country Park", "Segment du Wilson Trail Étape 4 (12 km)", "Hauteur de l'émetteur : 10 m", "Voie d'escalade 'Suicide Wall' : difficulté 5.9", "Distance du MTR : 3 km (Diamond Hill)"],
    },
