    type: "landmark",
    name: { de: "Ap Chau", hu: "Ap Chau", ro: "Ap Chau", en: "Ap Chau" },
    coords: [114.2686, 22.5461],
    description: {
      de: "Ap Chau (Robinson Island) ist eine kleine Insel im Nordosten, bekannt für ihre ungewöhnliche Form. Die berühmteste Attraktion ist ein natürlicher Steinbogen.",
      hu: "Az Ap Chau (Robinson-sziget) egy kis sziget északkeleten, szokatlan alakjáról ismert. Legismertebb látnivalója egy természetes kőív.",
      ro: "Ap Chau (Insula Robinson) este o insulă mică în nord-est, cunoscută pentru forma sa. Atracția principală este un arc natural de piatră.",
      en: "Ap Chau (Robinson Island) is a small island in the northeast known for its unusual shape. Its most famous feature is a natural rock arch.",
      es: "Ap Chau (Robinson Island) es una pequeña isla en el noreste, conocida por su forma inusual. Su atracción más famosa es un arco de piedra natural.",
      pt: "Ap Chau (Robinson Island) é uma pequena ilha no nordeste, conhecida pela sua forma invulgar. A sua atração mais famosa é um arco de pedra natural.",
      fr: "Ap Chau (Robinson Island) est une petite île du nord-est, connue pour sa forme inhabituelle. Son attraction la plus célèbre est une arche de pierre naturelle.",
    },
    facts: {
      de: ["Natürlicher Gesteinsbogen", "Besteht aus roter Brekzie", "Form einer Ente", "Insel im Double Haven"],
      hu: ["Természetes kőkapu", "Vörös breccsából áll", "Kacsa alakú sziget", "Double Haven öbölben van"],
      ro: ["Arc de piatră natural", "Format din brecie roșie", "Formă de rață", "Situată în Double Haven"],
      en: ["Natural rock arch feature", "Composed of red breccia", "Duck-shaped geography", "Located in Double Haven"],
      es: ["Arco de roca natural", "Compuesta de brecha roja", "Forma de un pato", "Isla en el Double Haven"],
      pt: ["Arco de rocha natural", "Composta por brecha vermelha", "Forma de um pato", "Ilha no Double Haven"],
      fr: ["Arche rocheuse naturelle", "Composée de brèche rouge", "Forme d'un canard", "Île de Double Haven"],
    },
    imageHint: "Ap Chau natural rock arch",
    descriptionAdvanced: {
      de: "Ap Chau, auch bekannt als Robinson Island, ist eine kleine, sichelförmige Insel im Double Haven im Nordosten der New Territories von Hongkong. Die Insel ist geologisch einzigartig, da sie fast vollständig aus roter Brekzie besteht, einem sedimentären Gestein, das ihr eine markante rötliche Farbe verleiht. Die berühmteste Formation ist das „Auge der Ente“, ein natürlicher Steinbogen am nördlichen Ende der Insel, der durch jahrtausendelange Erosion entstanden ist. Die Form der Insel erinnert aus der Luft tatsächlich an eine liegende Ente, was ihr den kantonesischen Namen eingebracht hat. Ap Chau ist Teil des UNESCO Global Geoparks von Hongkong und beherbergt ein kleines Besucherzentrum, das über die Geschichte der Hakka-Fischer informiert, die hier einst lebten. Die Gewässer um die Insel sind ruhig und klar, was sie zu einem beliebten Ziel für Öko-Touren macht. Wanderwege führen Besucher zu Aussichtspunkten, von denen man bis zum chinesischen Festland blicken kann.",
      hu: "Ap Chau, más néven Robinson-sziget, egy apró, kifli alakú sziget Hongkong északkeleti részén, a Double Haven öbölben. A sziget geológiai szempontból különleges, mivel vörös breccsa kőzetből épül fel, amely ritka jelenség a régióban és mélyvörös színt kölcsönöz a partoknak. Legismertebb látványossága a „Kacsa szeme” nevű természetes kőív, amelyet az évezredes erózió és a hullámverés formált a sziklába. A sziget alakja felülről nézve egy úszó kacsára emlékeztet, innen ered a neve is. Ap Chau része a Hongkongi UNESCO Globális Geoparknak, így a terület szigorú védelem alatt áll. A szigeten egy kis halászfalu is található, ahol a hakka közösség tagjai élnek, megőrizve hagyományos életmódjukat. A látogatók egy tanösvényen keresztül fedezhetik fel a sziget különleges sziklaformációit, miközben lenyűgöző kilátás nyílik a környező nyugodt öblökre és a kínai szárazföld közeli partjaira.",
      ro: "Ap Chau, cunoscută și sub numele de Insula Robinson, este o mică insulă situată în regiunea Double Haven din nord-estul Hong Kong-ului. Insula este celebră pentru geologia sa neobișnuită, fiind compusă aproape în totalitate din brecie roșie, o rocă sedimentară care îi conferă o nuanță distinctă de ocru și roșu. Cea mai fotografiată trăsătură a insulei este „Ochiul Raței”, un arc natural de piatră format prin eroziunea marină, situat în extremitatea nordică. Numele insulei în cantoneză se traduce prin „Insula Rață”, datorită formei sale geografice care seamănă izbitor cu o rață care plutește. Fiind parte a Geoparcului Global UNESCO din Hong Kong, Ap Chau este o destinație protejată, oferind trasee educaționale care explică formarea rocilor și istoria comunității locale Hakka. Satul de pescari de pe insulă este unul dintre cele mai izolate din regiune, păstrând un farmec tradițional. Este un loc ideal pentru amatorii de natură și geologie care doresc să exploreze peisajele sălbatice ale arhipelagului.",
      en: "Ap Chau, commonly known as Robinson Island, is a small, curved island located within the serene waters of Double Haven in Hong Kong's northeast New Territories. The island is a geological marvel, formed from layers of red breccia and conglomerate rocks that date back over 100 million years, giving the terrain a striking reddish hue. Its most iconic landmark is the \"Duck's Eye,\" a spectacular natural sea arch carved into the cliffs by centuries of wave action. When viewed from a distance, the island's silhouette remarkably resembles a duck huddling on the water, which gives it its local name. As a key site within the Hong Kong UNESCO Global Geopark, Ap Chau features a heritage trail and a small story room dedicated to the history of the Tanka and Hakka fishing communities. The surrounding marine environment is exceptionally calm, making it a favorite spot for kayakers and boat tours. From its highest points, visitors can enjoy panoramic views of the Shenzhen coastline just across the border.",
      es: "Ap Chau (Isla Redonda) es una pequeña isla en el noreste de Hong Kong, dentro del Parque Marino Yan Chau Tong. Tiene un diámetro de unos 300 m y es conocida por su roca granítica circular que forma una plataforma plana en la cima. La isla está deshabitada y es un destino popular para kayakistas y buceadores. El agua circundante es rica en vida marina. El nombre 'Ap Chau' significa 'Isla del Pato' en cantonés. Forma parte del Plover Cove Country Park y solo es accesible por barco, a menudo desde Lai Chi Wo. Presenta una geología única con rocas de arenisca roja.",
      pt: "Ap Chau (Round Island) é uma pequena ilha no nordeste de Hong Kong, no Parque Marinho Yan Chau Tong. A ilha tem um diâmetro de cerca de 300 m e é conhecida pela sua rocha de granito redonda, que forma uma plataforma plana no topo. A ilha é inabitada e é um destino popular para canoístas e mergulhadores. A água circundante é rica em vida marinha. O nome 'Ap Chau' significa 'Ilha do Pato' em cantonês. A ilha faz parte do Plover Cove Country Park e só é acessível por barco, muitas vezes a partir de Lai Chi Wo. Oferece uma geologia única com rochas de arenito vermelho.",
      fr: "Ap Chau (Round Island) est une petite île située au nord-est de Hong Kong, dans le parc marin de Yan Chau Tong. L'île a un diamètre d'environ 300 m et est connue pour son rocher granitique rond qui forme une plateforme plate au sommet. L'île est inhabitée et constitue une destination populaire pour les kayakistes et les plongeurs. Les eaux environnantes sont riches en vie marine. Le nom 'Ap Chau' signifie 'île aux canards' en cantonais. L'île fait partie du Plover Cove Country Park. Elle n'est accessible qu'en bateau, souvent depuis Lai Chi Wo. L'île offre une géologie unique avec des roches de grès rouge.",
    },
